mapper.select:
SELECT user_id AS userId, last_seen_at AS lastSeenAt
FROM user_presence
WHERE status <> 'OFFLINE' AND last_seen_at <= #{cutoff}

mapper.update:
UPDATE user_presence
SET status = 'OFFLINE', activity_type = NULL, activity_name = NULL,
    activity_started_at = NULL, updated_at = #{now}
WHERE user_id = #{userId} AND status <> 'OFFLINE'
  AND last_seen_at = #{lastSeenAt} AND last_seen_at <= #{cutoff}
